import{_ as i,o as e,c as a,a3 as s}from"./chunks/framework.CVt6dz2a.js";const k=JSON.parse('{"title":"EP.23 让世界有了重力","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.23-physics-engine.md","filePath":"comics/EP.23-physics-engine.md","lastUpdated":1793881879000}'),o={name:"comics/EP.23-physics-engine.md"};function d(l,t,n,h,r,c){return e(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="ep-23-让世界有了重力" tabindex="-1">EP.23 让世界有了重力 <a class="header-anchor" href="#ep-23-让世界有了重力" aria-label="Permalink to &quot;EP.23 让世界有了重力&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/23-physics/basics">23.1 基础入门：物理引擎与第一个下落小球</a> 延伸阅读：<a href="./../guide/23-physics/advanced">23.2 进阶应用：刚体碰撞与角色控制器</a> · <a href="./../guide/23-physics/practice">23.3 实战案例：3D 闯关小游戏</a> 动手演示：<a href="./../public/demos/physics/physics-basic.html">physics-basic 第一个下落小球</a> · <a href="./../public/demos/physics/character-controller.html">character-controller 角色控制器</a> · <a href="./../public/demos/physics/mini-game.html">mini-game 3D 闯关小游戏</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>像素酱给游戏主角手写&quot;跳跃动画&quot;，改了二十版缓动曲线还是一眼假，被标签君当场吐槽：像提线木偶。</td></tr><tr><td>② 揭秘</td><td>码叔在白板上画出两个世界：物理世界只算坐标，渲染世界只管画面——动画是剧本，物理是自然法则。</td></tr><tr><td>③ 实证</td><td>三十行 cannon-es：松手的小球真实弹跳，<code>collide</code> 事件顺手挂了金币音效，调参从&quot;改曲线&quot;变成&quot;填物理量&quot;。</td></tr><tr><td>④ 结案</td><td>坑点清单：步长太大穿地、渲染忘抄坐标、滥用三角面碰撞体。码叔总结：动画演轨迹，物理算轨迹。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-手搓动画的天花板-轨迹是写死的" tabindex="-1">① 手搓动画的天花板：轨迹是写死的 <a class="header-anchor" href="#_1-手搓动画的天花板-轨迹是写死的" aria-label="Permalink to &quot;① 手搓动画的天花板：轨迹是写死的&quot;">​</a></h3><ul><li><code>ball.y = Math.abs(Math.sin(t)) * h</code> 这类式子本质是&quot;导演排练&quot;：每一帧在哪都是剧本写好的；</li><li>剧本里没有&quot;碰撞&quot;这个概念：球不会被别人撞偏，也不能被玩家推一把；</li><li>地面换个高度、场景加一阵风，剧本就得重排——物理引擎只需要改一个参数。</li></ul><h3 id="_2-物理世界与渲染世界分离" tabindex="-1">② 物理世界与渲染世界分离 <a class="header-anchor" href="#_2-物理世界与渲染世界分离" aria-label="Permalink to &quot;② 物理世界与渲染世界分离&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>渲染世界</th><th>物理世界</th></tr></thead><tbody><tr><td>库</td><td>Three.js</td><td>cannon-es / rapier</td></tr><tr><td>组成</td><td>Scene → Mesh</td><td>World → Body</td></tr><tr><td>职责</td><td>画面好不好看</td><td>坐标怎么算</td></tr><tr><td>可见性</td><td>被相机拍到</td><td>永远不可见</td></tr></tbody></table><p>每帧的同步纪律只有两步：先 <code>world.step(1/60, dt, 3)</code> 推进物理，再把 <code>body.position / quaternion</code> 抄给对应 Mesh。坐标系不用换算——cannon-es 与 Three.js 同为右手系、Y 轴朝上。</p><h3 id="_3-三十行真实弹跳-碰撞事件" tabindex="-1">③ 三十行真实弹跳 + 碰撞事件 <a class="header-anchor" href="#_3-三十行真实弹跳-碰撞事件" aria-label="Permalink to &quot;③ 三十行真实弹跳 + 碰撞事件&quot;">​</a></h3><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">world.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">step</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> /</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, dt, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mesh.position.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">copy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(body.position)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">playerBody.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addEventListener</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;collide&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">e</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 吃金币、播音效 */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p>弹性与摩擦写在 <code>ContactMaterial</code> 上，一对物理材质一份约定；把刚体的 <code>collisionResponse</code> 设为 <code>false</code>，它就变成&quot;只发事件、不弹开&quot;的感应区——金币和终点线都是这么做的。</p><h3 id="_4-手感是调出来的" tabindex="-1">④ 手感是调出来的 <a class="header-anchor" href="#_4-手感是调出来的" aria-label="Permalink to &quot;④ 手感是调出来的&quot;">​</a></h3><p>物理对了不等于手感好。两个经典技巧：<strong>土狼时间</strong>（走出边缘后 0.12 秒内仍能起跳）与<strong>跳跃缓冲</strong>（落地前 0.15 秒内按跳自动补跳），都用时间戳实现，二十行代码，把&quot;玩具手感&quot;变成&quot;专业手感&quot;。移动平台则用 kinematic 刚体 + velocity 驱动，摩擦才会真的载人。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：小球直接穿过地面？</strong> 步长太大的隧道效应。固定步长 <code>world.step(1/60, dt, 3)</code>，并给 dt 加上限截断，切后台回来就不会一步跨进地里。</li><li><strong>Q：画面一顿一顿，物理和渲染不同步？</strong> <code>step</code> 要放在渲染循环内、<code>render</code> 之前，每帧一次；要丝滑就抄 <code>body.interpolatedPosition</code> 而不是 <code>position</code>。</li><li><strong>Q：角色贴墙卡住或翻倒？</strong> 角色 ↔ 墙单独建一个摩擦为 0 的 ContactMaterial；<code>fixedRotation = true</code> 锁死旋转，记得 <code>updateMassProperties()</code>。</li><li><strong>Q：站上移动平台不被带走？</strong> 平台必须是 kinematic 且每帧写 velocity 驱动；每帧瞬移 position 的平台在物理上&quot;没有速度&quot;，摩擦无从产生。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>物理世界与渲染世界各自负责什么？它们之间每帧的同步顺序是什么？</li><li>为什么金币要做成 <code>collisionResponse = false</code> 的感应体？收集时必须处理哪三件事？</li><li>土狼时间和跳跃缓冲分别解决什么手感问题？为什么用时间戳而不是布尔标志？</li></ol><details><summary>答案</summary><ol><li>物理世界（cannon-es 的 World/Body）按物理规律计算坐标与姿态，永远不可见；渲染世界（Three.js 的 Scene/Mesh）只负责画面。每帧先 <code>world.step(1/60, dt, 3)</code> 推进物理，再把 <code>body.position / quaternion</code> 抄给对应 Mesh，最后 <code>renderer.render</code> 出画面。</li><li>感应体只发 <code>collide</code> 事件、不产生排斥力，角色穿过金币不会被弹开。收集三件事缺一不可：置 <code>taken</code> 标志去重（事件可能连发多帧）、<code>scene.remove</code> 下架网格、<code>world.removeBody</code> 物理除名（否则原地还踩着看不见的金币）。</li><li>土狼时间解决&quot;走出平台边缘按跳无反应&quot;——离地后 0.12 秒内仍允许起跳；跳跃缓冲解决&quot;落地瞬间按键被吞&quot;——落地前 0.15 秒内的跳跃键落地自动补跳。时间戳把&quot;状态&quot;变成&quot;事实记录&quot;，起跳条件是纯计算 <code>t - lastGrounded &lt; COYOTE</code>，没有标志清零的时机问题，调手感只需改一个秒数常量。</li></ol></details>`,20)])])}const u=i(o,[["render",d]]);export{k as __pageData,u as default};
